/* @autogenerated */
package net.civeira.phylax.feature.observe.metric;

import java.util.Arrays;

/**
 * Latency histogram with fixed buckets (milliseconds): 5, 10, 25, 50, 100, 250, 500, 1000, 2500,
 * 5000, 10000 and above. Fixed buckets add up exactly between minutes, hours and sources, and the
 * percentiles come from a linear interpolation inside the bucket (within ~10 % of the real value).
 */
public final class Histogram {

  /** Upper limits of the buckets; the last bucket has no limit. */
  public static final double[] LIMITS = {5, 10, 25, 50, 100, 250, 500, 1000, 2500, 5000, 10000};

  private final long[] counts;

  public Histogram() {
    this.counts = new long[LIMITS.length + 1];
  }

  public Histogram(final long[] counts) {
    this.counts = null == counts || counts.length != LIMITS.length + 1 ? new long[LIMITS.length + 1]
        : counts.clone();
  }

  public void add(final double millis) {
    int index = Arrays.binarySearch(LIMITS, millis);
    counts[index >= 0 ? index : -index - 1]++;
  }

  public Histogram merge(final long[] other) {
    if (null != other && other.length == counts.length) {
      for (int i = 0; i < counts.length; i++) {
        counts[i] += other[i];
      }
    }
    return this;
  }

  public long[] counts() {
    return counts.clone();
  }

  public long total() {
    return Arrays.stream(counts).sum();
  }

  /**
   * @param quantile 0..1 (0.95 for p95)
   * @return the estimated value in milliseconds, or null without data
   */
  public Double percentile(final double quantile) {
    long total = total();
    if (total == 0) {
      return null;
    }
    double rank = quantile * total;
    long seen = 0;
    for (int i = 0; i < counts.length; i++) {
      if (counts[i] > 0 && seen + counts[i] >= rank) {
        double low = i == 0 ? 0 : LIMITS[i - 1];
        double high = i < LIMITS.length ? LIMITS[i] : LIMITS[LIMITS.length - 1] * 2;
        double inside = (rank - seen) / counts[i];
        return low + (high - low) * Math.max(0, Math.min(1, inside));
      }
      seen += counts[i];
    }
    return LIMITS[LIMITS.length - 1] * 2;
  }
}
